//! The shared CUDA device handle.
//!
//! candle needs an explicit `Device` to place tensors on; opening
//! CUDA device 0 builds a CUDA context, so we do it once and share
//! the handle (it is cheap to clone -- an `Arc` inside). Every op
//! that materializes a tensor goes through `cuda_device`.

use candle_core::Device;
use std::sync::OnceLock;

static CUDA: OnceLock<Device> = OnceLock::new();

/// Borrow the process-wide CUDA device 0, initializing it on first
/// use.
///
/// # Panics
/// Panics if the candle CUDA backend cannot open device 0 (no GPU,
/// driver/toolkit mismatch). Callers reach this only under the
/// `cuda` feature on Linux/x86_64, where a GPU is presumed present;
/// the device(...) dispatch layer is responsible for the
/// feature/target gating that keeps non-GPU hosts off this path.
pub fn cuda_device() -> &'static Device {
    CUDA.get_or_init(|| Device::new_cuda(0).expect("CUDA device 0 initializes"))
}

