12	///
13	/// # Errors
14	/// `RankMismatch` if `a` is not rank 2; `ShapeMismatch` if `b`'s
15	/// leading dim does not match `a`'s `k`; `LabelMismatch` on
16	/// disagreeing contraction labels.
17	pub fn matmul(a: &DenseArray, b: &DenseArray) -> Result<DenseArray, ArrayError> {
18	    let (m, k) = match a.shape().dims() {
19	        [m, k] => (*m, *k),
20	        _ => {
21	            return Err(ArrayError::RankMismatch {
22	                expected: 2,
23	                got: a.rank(),
24	            });
25	        }
26	    };
27	    let result_labels = matmul_labels(a, b)?;
28	    match b.shape().dims() {
29	        [k2, n] if *k2 == k => {
30	            let n = *n;
31	            let data = compute(a.data(), b.data(), &[m, k], &[k, n]);
32	            finalize(Shape::new(vec![m, n]), data, result_labels)
33	        }
34	        [k2] if *k2 == k => {
35	            let data = compute(a.data(), b.data(), &[m, k], &[k]);
36	            finalize(Shape::vector(m), data, result_labels)
37	        }
38	        _ => Err(ArrayError::ShapeMismatch {
39	            source: k,
